using WAID.Application.Services;using WAID.Infrastructure.Persistence;namespace WAID.Infrastructure.Tests;public sealed class LiveMonitoringPersistenceTests
{
 [Fact]public async Task Sessions_samples_gaps_failures_and_retention_round_trip(){var path=Path.Combine(Path.GetTempPath(),$"waid-monitor-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var repo=new SqliteLiveMonitoringRepository(db);var id=Guid.NewGuid();var now=DateTimeOffset.UtcNow;var options=LiveMonitoringOptions.Default;await repo.SaveSessionAsync(new(id,now,null,LiveMonitoringState.Running,options,""),CancellationToken.None);var samples=Enumerable.Range(0,5).Select(i=>new LiveSignalSample(Guid.NewGuid(),id,"cpu",now.AddMinutes(-i),20+i,"percent",LiveSignalSeverity.Normal,"test",TimeSpan.FromMilliseconds(2))).ToArray();var gap=new MonitoringGap(Guid.NewGuid(),id,now,now,MonitoringGapReason.SchedulingDelay,"gap");var failure=new CollectorFailure(Guid.NewGuid(),id,"collector",now,"code","safe");await repo.SaveCycleAsync(samples,[gap],[failure],CancellationToken.None);var retention=await repo.ApplyRetentionAsync(now.AddDays(-1),3,CancellationToken.None);var loaded=await repo.GetLatestAsync(10,CancellationToken.None);Assert.NotNull(loaded);Assert.Equal(3,loaded.Samples.Count);Assert.Single(loaded.Gaps);Assert.Single(loaded.Failures);Assert.Equal(3,retention.MaximumSamples);}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}
 [Fact]public async Task Restart_recovery_closes_interrupted_session(){var path=Path.Combine(Path.GetTempPath(),$"waid-monitor-recovery-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var repo=new SqliteLiveMonitoringRepository(db);var session=new LiveMonitoringSession(Guid.NewGuid(),DateTimeOffset.UtcNow,null,LiveMonitoringState.Running,LiveMonitoringOptions.Default,"");await repo.SaveSessionAsync(session,CancellationToken.None);await repo.RecoverInterruptedSessionsAsync(DateTimeOffset.UtcNow,CancellationToken.None);var loaded=await repo.GetLatestAsync(10,CancellationToken.None);Assert.NotNull(loaded!.Session.EndedAtUtc);Assert.Contains("restarted",loaded.Session.StopReason,StringComparison.OrdinalIgnoreCase);}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}
}
